/// Long name for a MsgType value (e.g. "D" -> "NewOrderSingle"); empty if
/// unknown. Linear scan over the message table (cold path: tooling only).
[[nodiscard]] constexpr std::string_view msg_type_name(std::string_view value) noexcept {
    for (auto const& e : detail::msg_type_names)
        if (e.value == value)
            return e.name;
    return {};
}

